IFERROR(__xludf.DUMMYFUNCTION("IF(A4="""", """", 
   IF(AC4>30, 0,
      IFERROR(
        LET(
          data, IMPORTRANGE(B4, ""'""&A4&""'!A:M""),
          dates, INDEX(data,,1),
          texts, INDEX(data,,13),
          INDEX(
            ARRAYFORMULA(
              VALUE(
       "&"         REGEXEXTRACT(
                  FILTER(
                    texts,
                    dates <= Z4,
                    REGEXMATCH(texts, ""预入|待生产""),
                    NOT(REGEXMATCH(texts, ""截单""))
                  ),
                  ""(?:"&"预入)(\d+)""
                )
              )
            ),
            1
          )
        ),
        0
      )
   )
)"),"#REF!")

